    },
    "next_actions": [
      {
        "action_id": "PMO_STATUS_REQUEST",
        "description": "Send internal PMO status request for Project Orion Phase 2 (current phase, milestones, deliverables, timelines, risks, dependencies). Target response within 2 business days."
      },
      {
        "action_id": "TRACKER_RETRIEVAL",
        "description": "Fetch latest data from the Project Orion tracker and reconcile with PO GS-78432."
      },
      {
        "action_id": "DISPATCH_STAKEHOLDER_EMAIL",
        "description": "Dispatch the stakeholder email to Global Shipper finance recipients once PMO status is obtained and briefing is finalized."
      }
    ],
